# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ESKİ ÇAĞ MEDENİYETLERİNDE HUKUK KURALLARI (MEZOPOTAMYA VE ANADOLU)</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. URKAGİNA KANUNLARI</text>\n  <text x="125" y="84" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e3a8a">Sümerler — Lagaş (MÖ ~2375)</text>\n  <text x="125" y="106" text-anchor="middle" font-size="10" fill="#1d4ed8">• Tarihte bilinen İLK YAZILI</text>\n  <text x="125" y="122" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">hukuk kurallarıdır.</text>\n  <text x="125" y="144" text-anchor="middle" font-size="10" fill="#1d4ed8">• Rahip-kralların yolsuzluğunu</text>\n  <text x="125" y="160" text-anchor="middle" font-size="10" fill="#1d4ed8">önlemiş; dul, yetim ve yoksulu</text>\n  <text x="125" y="176" text-anchor="middle" font-size="10" fill="#1d4ed8">korumuştur.</text>\n  <text x="125" y="200" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">• Cezalar FİDYE (bedel/tazminat)</text>\n  <text x="125" y="216" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">esasına dayanır (İnsancıl).</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">2. HAMMURABİ KANUNLARI</text>\n  <text x="350" y="84" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7f1d1d">Babiller (MÖ 18. Yüzyıl — 282 Madde)</text>\n  <text x="350" y="106" text-anchor="middle" font-size="10" fill="#991b1b">• Tanrı Şamaş önünde dikili taş</text>\n  <text x="350" y="122" text-anchor="middle" font-size="10" fill="#991b1b">stelde yazılıdır.</text>\n  <text x="350" y="144" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">• KISASA KISAS (Göze göz,</text>\n  <text x="350" y="160" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">dişe diş) ilkesi esastır.</text>\n  <text x="350" y="182" text-anchor="middle" font-size="10" fill="#991b1b">• Sosyal sınıf farkı (soylu, hür,</text>\n  <text x="350" y="198" text-anchor="middle" font-size="10" fill="#991b1b">köle) cezalarda belirleyicidir;</text>\n  <text x="350" y="214" text-anchor="middle" font-size="10" fill="#991b1b">mülkiyet ve aile hukuku gelişmiştir.</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">3. HİTİT KANUNLARI</text>\n  <text x="575" y="84" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">Anadolu Medeniyeti (Hattuşa)</text>\n  <text x="575" y="106" text-anchor="middle" font-size="10" fill="#166534">• Kısas yerine TAZMİNAT ve</text>\n  <text x="575" y="122" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">iş gücü/bedel ödeme esastır.</text>\n  <text x="575" y="144" text-anchor="middle" font-size="10" fill="#166534">• Evlenme, boşanma, çeyiz ve</text>\n  <text x="575" y="160" text-anchor="middle" font-size="10" fill="#166534">medeni hukuk düzenlenmiştir.</text>\n  <text x="575" y="182" text-anchor="middle" font-size="10" fill="#166534">• Kölelere mülk edinme ve</text>\n  <text x="575" y="198" text-anchor="middle" font-size="10" fill="#166534">evlenme hakkı tanımış, hayvan</text>\n  <text x="575" y="214" text-anchor="middle" font-size="10" fill="#166534">ve bitkileri korumuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İBRANİ HUKUKU (ON EMİR), ROMA (12 LEVHA) VE TÜRK TÖRESİ</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">1. ON EMİR (İBRANİLER)</text>\n  <text x="125" y="84" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">İlahî Kaynaklı Hukuk (Hz. Musa)</text>\n  <text x="125" y="108" text-anchor="middle" font-size="10" fill="#78350f">• Tek Tanrı inancına dayanan</text>\n  <text x="125" y="124" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">ilahî emirlerdir (Sina Dağı).</text>\n  <text x="125" y="148" text-anchor="middle" font-size="10" fill="#78350f">• Öldürmeyeceksin, çalmayacaksın,</text>\n  <text x="125" y="164" text-anchor="middle" font-size="10" fill="#78350f">yalancı şahitlik etmeyeceksin,</text>\n  <text x="125" y="180" text-anchor="middle" font-size="10" fill="#78350f">anne-babana saygı duyacaksın</text>\n  <text x="125" y="196" text-anchor="middle" font-size="10" fill="#78350f">gibi evrensel ahlak-hukuk ilkeleri.</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">2. ON İKİ LEVHA KANUNLARI</text>\n  <text x="350" y="84" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#581c87">Roma Medeniyeti (MÖ 450)</text>\n  <text x="350" y="108" text-anchor="middle" font-size="10" fill="#6b21a8">• Patriciler (soylular) ile</text>\n  <text x="350" y="124" text-anchor="middle" font-size="10" fill="#6b21a8">Plebler (halk) arasındaki sınıf</text>\n  <text x="350" y="140" text-anchor="middle" font-size="10" fill="#6b21a8">mücadelesi sonucunda yazıldı.</text>\n  <text x="350" y="164" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">• BUGÜNKÜ MODERN AVRUPA</text>\n  <text x="350" y="180" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">HUKUKUNUN TEMELİDİR</text>\n  <text x="350" y="202" text-anchor="middle" font-size="10" fill="#6b21a8">(Sonradan Justinianus Kanunları).</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">3. TÜRK TÖRESİ (TÜRKİSTAN)</text>\n  <text x="575" y="84" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e3a8a">Sözlü Hukuk — «İl Bırakılır, Töre Bırakılmaz»</text>\n  <text x="575" y="108" text-anchor="middle" font-size="10" fill="#1d4ed8">• Kaynağı: Kut, Kurultay kararları,</text>\n  <text x="575" y="124" text-anchor="middle" font-size="10" fill="#1d4ed8">hakan buyrukları ve gelenekler.</text>\n  <text x="575" y="148" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">• 4 Değişmez İlke: Könilik (Adalet),</text>\n  <text x="575" y="164" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">Uzluk (İyilik), Tüzlük (Eşitlik),</text>\n  <text x="575" y="180" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">Kişilik (İnsanlık).</text>\n  <text x="575" y="204" text-anchor="middle" font-size="10" fill="#b91c1c">• Konargöçerlik → Kısa süreli hapis.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ESKİ ÇAĞ TOPLUMLARINDA İNANÇ - BİLİM VE SANAT İLİŞKİSİ (TAR.9.2.3)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">İNANÇ VE İHTİYAÇLARDAN DOĞAN BİLİMLER</text>\n  <text x="35" y="94" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Mezopotamya (Sümer / Babil):</text>\n  <text x="45" y="110" font-size="10" fill="#1d4ed8">Ziggurat (Tapınak + Gözlemevi + Depo) → Astronomi,</text>\n  <text x="45" y="126" font-size="10" fill="#1d4ed8">Ay yılı takvimi, 60 tabanlı sayı sistemi, çivi yazısı.</text>\n  <text x="35" y="150" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Mısır Medeniyeti:</text>\n  <text x="45" y="166" font-size="10" fill="#1d4ed8">Ölümden sonra yaşam inancı → Mumyacılık → Tıp, anatomi,</text>\n  <text x="45" y="182" font-size="10" fill="#1d4ed8">eczacılık. Nil taşkınları → Geometri, Güneş yılı takvimi,</text>\n  <text x="45" y="198" font-size="10" fill="#1d4ed8">pi (π) sayısı, hiyeroglif yazısı ve papirüs.</text>\n  <text x="35" y="220" font-size="10.5" font-weight="bold" fill="#b91c1c">• Fenike Harf Alfabesi · İyon Felsefe ve Bilimi</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">ESKİ ÇAĞDA MİMARİ VE SANAT ANLAYIŞI</text>\n  <text x="375" y="96" font-size="10.5" font-weight="bold" fill="#14532d">• Mısır: Firavunlar için anıtsal Piramitler (Keops)</text>\n  <text x="385" y="112" font-size="10" fill="#166534">ve Sfenks heykelleri (Tanrı-kral ve ahiret inancı).</text>\n  <text x="375" y="136" font-size="10.5" font-weight="bold" fill="#14532d">• Anadolu (Hitit): İvriz ve Yazılıkaya kabartmaları,</text>\n  <text x="385" y="152" font-size="10" fill="#166534">Aslanlı Kapı; tanrılara hesap için Anal (Yıllık) yazımı.</text>\n  <text x="375" y="176" font-size="10.5" font-weight="bold" fill="#14532d">• Yunan &amp; Roma: Tapınaklar (Parthenon), insan</text>\n  <text x="385" y="192" font-size="10" fill="#166534">ölçülerinde gerçekçi heykeller, Kolezyum, su kemerleri.</text>\n  <text x="375" y="216" font-size="10.5" font-weight="bold" fill="#b45309">• Türkistan: Hayvan Üslubu, Kurganlar, Altın Elbiseli Adam.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
